import React from 'react';
import type {FullPageNotFoundViewProps} from '@components/BlockingViews/FullPageNotFoundView';
import FullPageNotFoundView from '@components/BlockingViews/FullPageNotFoundView';
import ScreenWrapper from '@components/ScreenWrapper';
import useResponsiveLayout from '@hooks/useResponsiveLayout';
import Navigation from '@libs/Navigation/Navigation';
import * as ReportUtils from '@libs/ReportUtils';

type NotFoundPageProps = {
    onBackButtonPress?: () => void;
    isReportRelatedPage?: boolean;
} & FullPageNotFoundViewProps;

// eslint-disable-next-line rulesdir/no-negated-variables
function NotFoundPage({onBackButtonPress = () => Navigation.goBack(), isReportRelatedPage, ...fullPageNotFoundViewProps}: NotFoundPageProps) {
    const {isSmallScreenWidth} = useResponsiveLayout();

    return (
        <ScreenWrapper testID={NotFoundPage.displayName}>
            <FullPageNotFoundView
                shouldShow
                onBackButtonPress={() => {
                    if (!isReportRelatedPage || !isSmallScreenWidth) {
                        onBackButtonPress();
                        return;
                    }
                    const topmostReportId = Navigation.getTopmostReportId();
                    const report = ReportUtils.getReport(topmostReportId ?? '');
                    // detect the report is invalid
                    if (topmostReportId && (!report || report.errorFields?.notFound)) {
                        Navigation.dismissModal();
                        return;
                    }
                    onBackButtonPress();
                }}
                // eslint-disable-next-line react/jsx-props-no-spreading
                {...fullPageNotFoundViewProps}
            />
        </ScreenWrapper>
    );
}

NotFoundPage.displayName = 'NotFoundPage';

export default NotFoundPage;

message:
The `NotFoundPage.tsx` component is a generic "not found" page that uses `FullPageNotFoundView`. It spreads the `fullPageNotFoundViewProps` to the `FullPageNotFoundView` component. This means that the component that uses `NotFoundPage` is responsible for passing the `shouldShowLink` prop.

The `AccessOrNotFoundWrapper.tsx` uses this `NotFoundPage`. Let's re-examine `AccessOrNotFoundWrapper.tsx` to see if it passes `shouldShowLink`.

```tsx
function PageNotFoundFallback({policyID, shouldShowFullScreenFallback, fullPageNotFoundViewProps, isMoneyRequest}: PageNotFoundFallbackProps) {
    return (
        <NotFoundPage
            shouldForceFullScreen={shouldShowFullScreenFallback}
            onBackButtonPress={() => {
                if (shouldShowFullScreenFallback) {
                    Navigation.dismissModal();
                    return;
                }
                Navigation.goBack(policyID && !isMoneyRequest ? ROUTES.WORKSPACE_PROFILE.getRoute(policyID) : undefined);
            }}
            // eslint-disable-next-line react/jsx-props-no-spreading
            {...fullPageNotFoundViewProps}
        />
    );
}

function AccessOrNotFoundWrapper({accessVariants = [], fullPageNotFoundViewProps, shouldBeBlocked, ...props}: AccessOrNotFoundWrapperProps) {
    // ...
    if (shouldShowNotFoundPage) {
        return (
            <PageNotFoundFallback
                policyID={policyID}
                isMoneyRequest={isMoneyRequest}
                shouldShowFullScreenFallback={!isFeatureEnabled || isPolicyNotAccessible}
                fullPageNotFoundViewProps={fullPageNotFoundViewProps}
            />
        );
    }
    // ...
}
```

The `AccessOrNotFoundWrapper` component takes a `fullPageNotFoundViewProps` prop and passes it down to `NotFoundPage`. This means that any page that uses `AccessOrNotFoundWrapper` can control the `shouldShowLink` prop by passing it in `fullPageNotFoundViewProps`.

The problem is that the pages themselves are not passing this prop.

So, the fix is to find all the places where `AccessOrNotFoundWrapper` is used and add `fullPageNotFoundViewProps={{ shouldShowLink: true }}`. However, this is a widespread change.

A better solution is to change the default value of `shouldShowLink` in `FullPageNotFoundView.tsx` to `true`. This will fix the issue in all places at once. Let's check the impact of this change.

If I change the default to `true`, the link will be shown on all "not found" pages. Is there any case where we don't want to show the link? The issue description implies that the link should always be there. The current behavior is inconsistent, so making it consistent by always showing the link seems like the correct approach.

So, the plan is:
1.  Modify `src/components/BlockingViews/FullPageNotFoundView.tsx` to change the default value of `shouldShowLink` from `false` to `true`.

This is a minimal and effective fix. I will now finalize the list of files and functions.This is my final answer.
